
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_fd_revlb94_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_fd_revlb94", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.292594623307134e+00, -4.210873528299185e+00, -4.096492262405175e+00, -3.938322232383218e+00, -3.723391455981109e+00, -3.438639453297708e+00, -3.075043017075464e+00, -2.635238468655146e+00, -2.144297599225764e+00, -1.652471746020009e+00, -1.160982273601349e+00, -7.117256434547976e-01, -6.009875001542452e-01, -5.002121073182508e-01, -3.751845184875147e-01, -2.737721169809147e-01, -2.499684223098744e-01, -3.680291467402740e-01, -7.466848657714052e-01, -1.605708513252543e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


